describe('wall-clock is a non-authoritative liveness fault, not a divergent outcome (D1 fix 1)', () => {
  // The wall-clock / AbortSignal is time- and hardware-dependent: if it produced a `rule.timeout`
  // OUTCOME, a slow tier would disagree with a fast tier, breaking replay-determinism + the byte-identical
  // corpus. So it PROPAGATES as an infrastructure fault (RuleTimeout) rather than returning a result.
  // (An AbortSignal is the deterministic, hardware-independent way to trip the guard — the TS analog of
  // the .NET pre-cancelled CancellationToken.)
  const one = () => new FormRuleGraph(compile([rule('c.b', 'b', 'Compute', { '+': [{ var: 'a' }, 1] })]), fixedClock, testAdmission)

  it('evaluateInstance PROPAGATES RuleTimeout on an aborted signal (never a rule.timeout result)', () => {
    const ac = new AbortController()
    ac.abort()
    expect(() => one().evaluateInstance(instance({ a: 1 }), ac.signal)).toThrow(RuleTimeout)
  })

  it('reevaluate PROPAGATES RuleTimeout on an aborted signal', () => {
    const g = one()
    g.evaluateInstance(instance({ a: 1 }))
    const ac = new AbortController()
    ac.abort()
    expect(() => g.reevaluate('a', valueSnapshot(2), ac.signal)).toThrow(RuleTimeout)
  })

  it('a guard PROPAGATES RuleTimeout on an aborted signal (not a Validity verdict)', () => {
    const ac = new AbortController()
    ac.abort()
    const gd = new GuardEvaluator(fixedClock)
    const r: RuleDefinition = { id: 'g.min', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { '>': [{ var: 'amount' }, 50] } }
    expect(() => gd.evaluateGuard(r, snapshot({ amount: 100 }), testAdmission, ac.signal)).toThrow(RuleTimeout)
  })

  it('the op-budget, by contrast, STAYS an authoritative fail-closed OUTCOME (deterministic across tiers)', () => {
    // Distinct from the wall-clock: the op-budget is deterministic (same op count on both tiers), so it
    // remains an outcome-affecting fail-closed result — the two tiers reach it identically.
    const g = new FormRuleGraph(compile([rule('c.b', 'b', 'Compute', { '+': [{ var: 'a' }, 1] })]), fixedClock, testAdmission, {
      maxGraphNodes: 5000, maxTableRowsPerAggregate: 2000, maxDependencyDepth: 64, maxReferencesPerRule: 64,
      maxAstNodes: 256, maxLiteralLength: 4096, maxStaticWork: DEFAULT_LIMITS.maxStaticWork, stepBudget: 0, wallClockMs: 250,
    })
    const res = g.evaluateInstance(instance({ a: 1 }))
    expect(res.isSaveBlocked).toBe(true)
    expect(res.validations[0].validity?.error?.code).toBe(Codes.budgetExceeded)
  })
})

describe('unavailable aggregate refuses — never a fabricated null (ticket 162)', () => {
  it('an agg node the compiler cannot statically register is a publish-time refusal, not runtime data', () => {
    // Arity-4 (and expression-valued/non-string-arg) agg nodes used to skip reference
    // extraction, register no fold cell, and then refuse per-keystroke at runtime with no
    // authoring-time signal — permanently un-saveable data. The compiler now refuses them
    // (150-family direction), identically in both tiers.
    const bad = (expression: Json) => (() => { try { compile([rule('c.dyn', 'dyn', 'Compute', expression)]); return null } catch (e) { return e } })()
    for (const expression of [
      { agg: ['sum', 'items', 'amount', 'extra'] } as Json, // arity 4
      { agg: ['sum', { var: 'field.section' }, 'amount'] } as Json, // expression-valued arg (phantom String() cell before)
    ]) {
      const e = bad(expression)
      expect(e).toBeInstanceOf(CompileError)
      expect((e as CompileError).code).toBe(Codes.compileBadGrammar)
    }
  })

  it('a compiled aggregate the evaluation context cannot provide refuses with the ONE shared shape', () => {
    // The guard tier's flat context bag carries no tables, so a well-formed agg reference is
    // unavailable data there: rule.bad_reference with params {agg: "section/fn/col"} — the
    // exact shape (and param order) the shared corpus pins byte-identically across tiers.
    const guard = new GuardEvaluator(fixedClock)
    const v: RuleDefinition = { id: 'g.total', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Compute', expression: { var: 'table.sum(items.amount)' } }
    expect(guard.evaluateValue(v, snapshot({}), testAdmission)).toEqual({
      state: 'Error',
      error: { code: Codes.badReference, params: { agg: 'items/sum/amount' } },
    })
  })
})

describe('guard evaluator (workflow transition guards)', () => {
  const guard = new GuardEvaluator(fixedClock)
  const g: RuleDefinition = { id: 'g.minAmount', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { '>': [{ var: 'amount' }, 50] } }

  it('passes when the guard holds', () => {
    expect(guard.evaluateGuard(g, snapshot({ amount: 100 }), testAdmission)).toEqual({ ok: true })
  })

  it('fails closed with a stable code when the guard does not hold', () => {
    expect(guard.evaluateGuard(g, snapshot({ amount: 10 }), testAdmission)).toEqual({ ok: false, error: { code: 'g.minAmount', params: {} } })
  })

  it('does not treat an inherited object name as a supplied guard context value', () => {
    const inheritedName: RuleDefinition = { id: 'g.ownContextOnly', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { var: 'toString' } }
    expect(guard.evaluateGuard(inheritedName, snapshot({}), testAdmission)).toEqual({ ok: false, error: { code: 'g.ownContextOnly', params: {} } })
  })

  it('returns a refusal when a guard expression cannot compile', () => {
    const invalid: RuleDefinition = { id: 'g.invalid', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { unknown_operator: [] } }
    expect(guard.evaluateGuard(invalid, snapshot({}), testAdmission)).toEqual({ ok: false, error: { code: Codes.compileInvalidExpression, params: {} } })
  })

  it('refuses an uncaptured context even when the rule belongs to another tier', () => {
    const otherTier: RuleDefinition = { id: 'g.otherTier', tier: 'JsonSchema', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { type: 'object' } }
    expect(guard.evaluateGuard(otherTier, {} as RuleContextSnapshot, testAdmission)).toEqual({ ok: false, error: { code: Codes.contextSnapshotRequired, params: {} } })
  })

  it('keeps the other-tier guard neutral when the context is captured', () => {
    const otherTier: RuleDefinition = { id: 'g.otherTier', tier: 'JsonSchema', scope: 'Schema', scopeTarget: '', action: 'Validate', expression: { type: 'object' } }
    expect(guard.evaluateGuard(otherTier, snapshot({}), testAdmission)).toEqual({ ok: true })
  })

  it('evaluates a value expression', () => {
    const v: RuleDefinition = { id: 'g.fee', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Compute', expression: { 'money.mul': ['10', '3'] } }
    expect(guard.evaluateValue(v, snapshot({}), testAdmission)).toEqual({ state: 'Resolved', value: '30' })
  })

  it.each([
    ['guard', 'Validate', (evaluator: GuardEvaluator, rule: RuleDefinition) => evaluator.evaluateGuard(rule, snapshot({}), testAdmission)],
    ['value', 'Compute', (evaluator: GuardEvaluator, rule: RuleDefinition) => evaluator.evaluateValue(rule, snapshot({}), testAdmission)],
  ] as const)('names the responsible rule when a %s exceeds its step budget', (kind, action, evaluate) => {
    const evaluator = new GuardEvaluator(fixedClock, { ...DEFAULT_LIMITS, stepBudget: 0 })
    const rule: RuleDefinition = { id: `${kind}.budget`, tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action, expression: 1 }

    const result = evaluate(evaluator, rule)

    expect(result).toEqual(kind === 'guard'
      ? { ok: false, error: { code: Codes.budgetExceeded, params: { rule: rule.id } } }
      : { state: 'Error', error: { code: Codes.budgetExceeded, params: { rule: rule.id } } })
  })

  it('returns an error value when a value expression cannot compile', () => {
    const invalid: RuleDefinition = { id: 'g.invalidValue', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', action: 'Compute', expression: { unknown_operator: [] } }
    expect(guard.evaluateValue(invalid, snapshot({}), testAdmission)).toEqual({ state: 'Error', error: { code: Codes.compileInvalidExpression, params: {} } })
  })

  it('refuses an uncaptured value context even when the rule belongs to another tier', () => {
    const otherTier: RuleDefinition = { id: 'g.otherValueTier', tier: 'JsonSchema', scope: 'Schema', scopeTarget: '', action: 'Compute', expression: { type: 'object' } }
    expect(guard.evaluateValue(otherTier, {} as RuleContextSnapshot, testAdmission)).toEqual({ state: 'Error', error: { code: Codes.contextSnapshotRequired, params: {} } })
  })

  it('keeps the other-tier value neutral when the context is captured', () => {
    const otherTier: RuleDefinition = { id: 'g.otherValueTier', tier: 'JsonSchema', scope: 'Schema', scopeTarget: '', action: 'Compute', expression: { type: 'object' } }
    expect(guard.evaluateValue(otherTier, snapshot({}), testAdmission)).toEqual({ state: 'Resolved', value: null })
  })

  it.each([
    ['guard', (rule: RuleDefinition) => guard.evaluateGuard(rule, snapshot({}), testAdmission)],
    ['value', (rule: RuleDefinition) => guard.evaluateValue(rule, snapshot({}), testAdmission)],
  ])('propagates an unexpected compiler fault from %s evaluation', (_, evaluate) => {
    const failure = new Error('compiler infrastructure fault')
    const broken = new Proxy(g, { get(target, key, receiver) {
      if (key === 'tier') throw failure
      return Reflect.get(target, key, receiver)
    } })

    expect(() => evaluate(broken)).toThrow(failure)
  })

  it('fails closed on a pending dependency (server tier)', () => {
    expect(guard.evaluateGuard(g, snapshot({ amount: { '@pending': true } }), testAdmission)).toEqual({ ok: false, error: { code: Codes.pendingAtSave, params: {} } })
  })
})

