import { describe, it, expect } from 'vitest'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join, relative, sep } from 'node:path'
import {
  admitEnvironment, BorrowerEnvironmentCodes, builtInFunctions, compile, fieldReadEffect, FormRuleGraph, GuardEvaluator, lentGrammar,
  RuleContextSnapshot, RuleInstance, RuleRowSnapshot, RuleValueSnapshot, type BorrowerEnvironmentDeclaration, type EvaluationPhase, type RuleDefinition,
} from '../index.js'

const clock = () => new Date('2026-09-24T00:00:00Z')
const allPhases = { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }
const declaration = (over: Partial<BorrowerEnvironmentDeclaration> = {}): BorrowerEnvironmentDeclaration => ({
  borrower: 'ts-tests', grammar: lentGrammar, variables: { field: 't', row: 't' }, operations: builtInFunctions.map((f) => f.key),
  effects: [fieldReadEffect], missingValues: 'missing-field-reads-null', timeSource: 'injected', timeZone: 'utc', phases: allPhases, replay: 'deterministic', ...over,
})
const admitted = admitEnvironment(declaration()).forPhase('Run')
const code = (f: () => unknown) => { try { f() } catch (e) { return (e as { code?: string }).code } return undefined }
const rule = (id: string, scopeTarget: string, expression: unknown, action: RuleDefinition['action'] = 'Compute'): RuleDefinition =>
  ({ id, tier: 'JsonLogic', scope: 'Field', scopeTarget, action, expression: expression as RuleDefinition['expression'] })
const engineCode = (r: { validations: readonly { ruleId: string; validity?: { error?: { code: string } } }[] }) =>
  r.validations.find((o) => o.ruleId === 'rule.engine')?.validity?.error?.code

describe('T-590 borrower environment admission (TS reactive tier)', () => {
  it('rules-ck-28: a typed borrower declaration is admitted; one missing a member, borrowing another grammar, asking for an effect, naming an unregistered function or leaving a phase unmarked refuses', () => {
    expect(admitEnvironment(declaration()).declaration.borrower).toBe('ts-tests')
    const refused: Partial<BorrowerEnvironmentDeclaration>[] = [
      { borrower: ' ' }, { grammar: 'harborline-jsonlogic/v2' }, { variables: {} }, { operations: ['cat', 'http.get'] },
      { effects: [fieldReadEffect, 'network'] }, { missingValues: '' }, { timeZone: '' },
      { phases: { Run: true } as unknown as Record<EvaluationPhase, boolean> }, { replay: '' },
    ]
    for (const over of refused) expect(code(() => admitEnvironment(declaration(over))), JSON.stringify(over)).toBe(BorrowerEnvironmentCodes.declarationRefused)
  })

  it('rules-eng-26: a phase the declaration marks inapplicable cannot be presented', () => {
    const env = admitEnvironment(declaration({ phases: { ...allPhases, Submission: false } }))
    expect(env.forPhase('Render').phase).toBe('Render')
    expect(code(() => env.forPhase('Submission'))).toBe(BorrowerEnvironmentCodes.phaseNotAdmitted)
  })

  it('rules-eng-26: guard and value overloads evaluate under an admitted declaration and refuse the unadmitted counterpart', () => {
    const guard = new GuardEvaluator(clock)
    const g = rule('g', 'ok', { '>': [{ var: 'amount' }, 10] }, 'Validate')
    const v = rule('v', 'out', { cat: ['a', { var: 'amount' }] })
    const context = RuleContextSnapshot.fromJsonText('{"amount":20}')
    expect(guard.evaluateGuard(g, context, admitted)).toEqual({ ok: true })
    expect(guard.evaluateValue(v, context, admitted)).toEqual({ state: 'Resolved', value: 'a20' })
    const notAdmitted = { code: BorrowerEnvironmentCodes.notAdmitted, params: {} }
    expect(guard.evaluateGuard(g, context, null)).toEqual({ ok: false, error: notAdmitted })
    expect(guard.evaluateValue(v, context, null)).toEqual({ state: 'Error', error: notAdmitted })
    // A structural look-alike is not evidence.
    expect(guard.evaluateGuard(g, context, { declaration: declaration(), phase: 'Run' })).toEqual({ ok: false, error: notAdmitted })
    const withoutCat = admitEnvironment(declaration({ operations: ['var', '>'] })).forPhase('Run')
    expect(guard.evaluateGuard(g, context, withoutCat)).toEqual({ ok: true })
    expect(guard.evaluateValue(v, context, withoutCat)).toEqual({ state: 'Error', error: { code: BorrowerEnvironmentCodes.operationNotAdmitted, params: {} } })
  })

  it('rules-eng-26: full graph evaluation evaluates under an admitted declaration and refuses the unadmitted counterpart', () => {
    const compiled = compile([rule('t', 'total', { '+': [{ var: 'a' }, 1] })])
    const instance = RuleInstance.fromJsonText('{"a":2}')
    expect(new FormRuleGraph(compiled, clock, admitted).evaluateInstance(instance).values.get('field:total')).toEqual({ state: 'Resolved', value: 3 })
    const refused = new FormRuleGraph(compiled, clock, null).evaluateInstance(instance)
    expect(engineCode(refused)).toBe(BorrowerEnvironmentCodes.notAdmitted)
    expect(refused.values.has('field:total')).toBe(false)
    const narrow = admitEnvironment(declaration({ operations: ['var'] })).forPhase('Run')
    expect(engineCode(new FormRuleGraph(compiled, clock, narrow).evaluateInstance(instance))).toBe(BorrowerEnvironmentCodes.operationNotAdmitted)
  })

  it('rules-eng-26: incremental graph evaluation (field change, row add, row remove) evaluates under admission and refuses the unadmitted counterpart', () => {
    const compiled = compile([rule('t', 'total', { var: 'table.sum(items.amount)' }), rule('d', 'double', { '*': [{ var: 'a' }, 2] })])
    const row = RuleRowSnapshot.fromJsonText('{"id":"r1","fields":{"amount":5}}')
    const graph = new FormRuleGraph(compiled, clock, admitted)
    graph.evaluateInstance(RuleInstance.fromJsonText('{"a":1}'))
    expect(graph.reevaluate('a', RuleValueSnapshot.fromJsonText('3')).values.get('field:double')).toEqual({ state: 'Resolved', value: 6 })
    expect(graph.addRow('items', row).values.get('field:total')).toEqual({ state: 'Resolved', value: 5 })
    expect(graph.removeRow('items', 'r1').values.get('field:total')).toEqual({ state: 'Resolved', value: 0 })
    const cases = [
      { admission: null, expected: BorrowerEnvironmentCodes.notAdmitted },
      { admission: admitEnvironment(declaration({ variables: { field: 't' } })).forPhase('Run'), expected: BorrowerEnvironmentCodes.variableNotAdmitted },
    ]
    for (const { admission, expected } of cases) {
      const refused = new FormRuleGraph(compiled, clock, admission)
      expect(engineCode(refused.evaluateInstance(RuleInstance.fromJsonText('{"a":1}')))).toBe(expected)
      expect(engineCode(refused.reevaluate('a', RuleValueSnapshot.fromJsonText('3')))).toBe(expected)
      expect(engineCode(refused.addRow('items', row))).toBe(expected)
      expect(engineCode(refused.removeRow('items', 'r1'))).toBe(expected)
    }
  })

  it('rules-eng-26: architecture fence — TS and React evaluation call sites are inventoried and each presents an admission', () => {
    const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..', '..', '..')
    const inventoried = ['projections/typescript/foundation/hlp.foundation.rule-authoring/src/compile.ts']
    const entry = /new FormRuleGraph\(|\.evaluateGuard\(|\.evaluateValue\(/g
    const skip = new Set(['node_modules', 'dist', '__tests__', 'bin', 'obj', 'hlp.foundation.rule-runtime'])
    const found: string[] = []
    const walk = (dir: string) => {
      for (const name of readdirSync(dir)) {
        if (skip.has(name)) continue
        const path = join(dir, name)
        if (statSync(path).isDirectory()) { walk(path); continue }
        if (!/\.tsx?$/.test(name) || /\.test\.tsx?$/.test(name)) continue
        const source = readFileSync(path, 'utf8')
        const matches = [...source.matchAll(entry)]
        if (matches.length === 0) continue
        found.push(relative(root, path).split(sep).join('/'))
        for (const m of matches) {
          const line = source.slice(m.index, source.indexOf('\n', m.index))
          expect(line.includes('.forPhase(') || line.includes('admission'), `${path}: ${line}`).toBe(true)
        }
      }
    }
    walk(join(root, 'projections', 'typescript'))
    walk(join(root, 'projections', 'react'))
    expect(found.sort()).toEqual(inventoried)
  })
})

src/__tests__/conformance.test.ts.source:
/**
 * The dual-tier conformance harness, TS side (SPINE-1 §6.1, §6.4). Loads the SAME
 * shared JSON corpus the .NET test project loads, runs each case through the TS engine,
 * and asserts the lowered AST + per-rule outcomes match byte-for-byte (canonical JSON).
 * Both tiers asserting against the one corpus is what proves the two evaluators agree.
 */
import { describe, it, expect } from 'vitest'
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

import type { Json, RuleDefinition } from '../model.js'
import { DEFAULT_LIMITS, type RuleEngineLimits } from '../limits.js'
import { compile } from '../compiler.js'
import { CompileError } from '../grammar.js'
import { FormRuleGraph } from '../graph.js'
import { GuardEvaluator, RuleContextSnapshot } from '../guard.js'
import { RuleInstance } from '../instance.js'
import { serializeComputedValue, serializeOutcome, write } from '../canonical.js'
import {
  compileDecisionTable,
  compileFormula,
  type DecisionCell,
  type DecisionTableSkin,
  type FormulaSkin,
  type NoMatch,
} from '../skins/index.js'
import { admitEnvironment as admitTestEnvironment, fieldReadEffect as testFieldRead, lentGrammar as testGrammar } from '../environment.js'
import { builtInFunctions as testBuiltIns } from '../functions.js'
// The suite's own borrower: the whole register, every scope token, every phase (T-590 rules-eng-26).
const testAdmission = admitTestEnvironment({ borrower: 'rule-engine-tests', grammar: testGrammar, variables: { field: 'test', row: 'test', wf: 'test', timer: 'test' }, operations: testBuiltIns.map((f) => f.key), effects: [testFieldRead], missingValues: 'missing-field-reads-null', timeSource: 'injected-test-clock', timeZone: 'utc', phases: { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }, replay: 'deterministic' }).forPhase('Run')

const here = dirname(fileURLToPath(import.meta.url))
const corpusDir = join(here, '..', '..', '..', '..', '..', '..', 'conformance', 'hlp.foundation.rule-runtime', 'corpus')
const artifactDir = join(here, '..', '..', '..', '..', '..', '..', 'artifacts', 'rule-runtime')

interface CorpusCase {
  name: string
  clock?: string
  /** Integer limits as numbers; `maxStaticWork` as a decimal string (T-818: it exceeds MAX_SAFE_INTEGER). */
  limits?: Record<string, number | string>
  definitionRules?: Array<Record<string, Json>>
  skin?: Record<string, Json>
  instance: Record<string, Json>
  expectedAst?: Record<string, Json>
  expectedCompiledExpression?: Record<string, Json>
  expectedOutcomes?: Record<string, Json>
  /** Ticket 162: the case pins a PUBLISH-TIME refusal — compile must throw this stable code. */
  expectedCompileError?: { code: string, params?: Record<string, string> }
  /** Ticket 162: evaluate this rule id through GuardEvaluator.evaluateValue over `instance` as the context bag. */
  guardValue?: string
  expectedGuardValue?: Record<string, Json>
}

function allCases(): CorpusCase[] {
  const out: CorpusCase[] = []
  for (const f of readdirSync(corpusDir).filter((p) => p.endsWith('.json')).sort()) {
    const root = JSON.parse(readFileSync(join(corpusDir, f), 'utf8')) as { cases: CorpusCase[] }
    out.push(...root.cases)
  }
  return out
}

function parseRule(r: Record<string, Json>): RuleDefinition {
  return {
    id: r.id as string,
    tier: r.tier as RuleDefinition['tier'],
    scope: r.scope as RuleDefinition['scope'],
    scopeTarget: (r.scopeTarget as string) ?? '',
    expression: r.expression as Json,
    action: r.action as RuleDefinition['action'],
    presentation: r.presentation as RuleDefinition['presentation'],
  }
}

// ADR 0146 D2 — corpus skin authoring JSON → the typed skin model → RuleDefinition (mirror of the .NET
// CorpusLoader skin parsing). A skin case exercises the identical downstream compile + eval path.
function compileSkin(s: Record<string, Json>): RuleDefinition {
  const kind = s.kind as string
  if (kind === 'decision-table') return compileDecisionTable(parseDecisionTableSkin(s))
  if (kind === 'formula') return compileFormula(parseFormulaSkin(s))
  throw new Error(`unknown skin kind '${kind}'`)
}

function parseDecisionTableSkin(s: Record<string, Json>): DecisionTableSkin {
  return {
    ruleId: s.ruleId as string,
    scope: s.scope as DecisionTableSkin['scope'],
    scopeTarget: (s.scopeTarget as string) ?? '',
    action: s.action as DecisionTableSkin['action'],
    hitPolicy: s.hitPolicy as DecisionTableSkin['hitPolicy'],
    inputs: s.inputs as string[],
    rows: (s.rows as Array<Record<string, Json>>).map((r) => ({
      when: (r.when as Array<Record<string, Json>>).map(parseCell),
      output: r.output as Json,
      priority: (r.priority as number) ?? 0,
    })),
    noMatch: parseNoMatch(s.noMatch as Record<string, Json>),
  }
}

function parseCell(c: Record<string, Json>): DecisionCell {
  if ('any' in c) return { kind: 'any' }
  if ('op' in c) return { kind: 'compare', op: c.op as string, value: c.value as Json }
  if ('range' in c) {
    const r = c.range as Record<string, Json>
    return { kind: 'range', loInclusive: r.lo ?? null, hiExclusive: r.hi ?? null }
  }
  throw new Error('a decision-table cell must be one of { any | op/value | range }')
}

function parseNoMatch(nm: Record<string, Json>): NoMatch {
  if ('catchAll' in nm) return { kind: 'catch-all' }
  if ('default' in nm) return { kind: 'default', value: nm.default as Json }
  throw new Error('noMatch must declare a `default` value or `catchAll: true` (board F1 — no silent null)')
}

function parseFormulaSkin(s: Record<string, Json>): FormulaSkin {
  return {
    ruleId: s.ruleId as string,
    scope: s.scope as FormulaSkin['scope'],
    scopeTarget: (s.scopeTarget as string) ?? '',
    action: s.action as FormulaSkin['action'],
    inputs: (s.inputs as Array<Record<string, Json>>).map((i) => ({ ref: i.ref as string, type: (i.type as string) ?? 'any' })),
    expression: s.expression as Json,
  }
}

function clockOf(c: CorpusCase): () => Date {
  const clockMs = c.clock ? new Date(c.clock).getTime() : new Date('2026-06-30T00:00:00Z').getTime()
  return () => new Date(clockMs)
}

/**
 * The rules the case DECLARES — the exact list handed to the compiler. Ticket 193 review: the
 * runner needs this separately from `runCase` so it can assert the compiled graph introduced no
 * rule the case never declared.
 */
function declaredRules(c: CorpusCase): RuleDefinition[] {
  return c.skin ? [compileSkin(c.skin)] : (c.definitionRules ?? []).map(parseRule)
}

// Mirror of the .NET CorpusLoader.ParseLimits key set.
function limitsOf(c: CorpusCase): RuleEngineLimits {
  const l = c.limits ?? {}
  const int = (key: string, fallback: number) => (l[key] as number | undefined) ?? fallback
  return {
    ...DEFAULT_LIMITS,
    maxGraphNodes: int('maxGraphNodes', DEFAULT_LIMITS.maxGraphNodes),
    maxDependencyDepth: int('maxDependencyDepth', DEFAULT_LIMITS.maxDependencyDepth),
    maxReferencesPerRule: int('maxReferencesPerRule', DEFAULT_LIMITS.maxReferencesPerRule),
    maxAstNodes: int('maxAstNodes', DEFAULT_LIMITS.maxAstNodes),
    stepBudget: int('stepBudget', DEFAULT_LIMITS.stepBudget),
    maxStaticWork: typeof l.maxStaticWork === 'string' ? BigInt(l.maxStaticWork) : DEFAULT_LIMITS.maxStaticWork,
  }
}

function runCase(c: CorpusCase) {
  const rules = declaredRules(c)
  const limits = limitsOf(c)
  const compiled = compile(rules, limits)
  const graph = new FormRuleGraph(compiled, clockOf(c), testAdmission, limits)
  const result = graph.evaluateInstance(RuleInstance.fromJsonText(JSON.stringify(c.instance)))
  return { compiled, result }
}

// Ticket 162: a case pinning a publish-time refusal — return the refusal compile raises.
function compileRefusal(c: CorpusCase): CompileError {
  try {
    compile((c.definitionRules ?? []).map(parseRule), limitsOf(c))
  } catch (e) {
    if (e instanceof CompileError) return e
    throw e
  }
  throw new Error(`case '${c.name}' expected a compile refusal and none was raised`)
}

function compileRefusalCode(c: CorpusCase): string {
  return compileRefusal(c).code
}

// Ticket 162: a case evaluating one rule through the guard tier (flat context bag; no tables).
function guardValueOutcome(c: CorpusCase): string {
  const rule = (c.definitionRules ?? []).map(parseRule).find((r) => r.id === c.guardValue)
  if (!rule) throw new Error(`case '${c.name}': guardValue names unknown rule '${c.guardValue}'`)
  return serializeComputedValue(new GuardEvaluator(clockOf(c)).evaluateValue(rule, RuleContextSnapshot.fromJsonText(JSON.stringify(c.instance)), testAdmission))
}

describe('SPINE-1 conformance corpus (TS tier — byte-identical to .NET)', () => {
  for (const c of allCases()) {
    it(c.name, () => {
      if (c.expectedCompileError) {
        const refusal = compileRefusal(c)
        expect(refusal.code).toBe(c.expectedCompileError.code)
        // T-818: a case that pins params pins them exactly in both tiers.
        if (c.expectedCompileError.params) expect(refusal.params).toEqual(c.expectedCompileError.params)
        return
      }
      if (c.guardValue) {
        expect(guardValueOutcome(c)).toBe(write(c.expectedGuardValue as Json))
        return
      }
      const { compiled, result } = runCase(c)

      // ADR 0146 D2 — pin the skin compiler's pre-lowering expression byte-identical to the .NET tier.
      if (c.expectedCompiledExpression) {
        for (const [ruleId, expected] of Object.entries(c.expectedCompiledExpression)) {
          const rule = compiled.rules.find((r) => r.source.id === ruleId)
          expect(rule, `expectedCompiledExpression names unknown rule '${ruleId}'`).toBeDefined()
          const produced = typeof rule!.source.expression === 'string'
            ? (JSON.parse(rule!.source.expression) as Json)
            : (rule!.source.expression as Json)
          expect(write(produced)).toBe(write(expected))
        }
      }

      // EXACT compiled set, not a lower bound (ticket 193 review): expectedCompiledExpression /
      // expectedAst name only the rules a case cares to pin, so neither notices a rule the compiler
      // INVENTED. Every compiled rule must trace back to a rule the case declared, once. (Subset, not
      // equality: the compiler deliberately drops Tier-1 JsonSchema rules — the kernel validator owns
      // those — so a declared rule legitimately need not compile.)
      const declaredIds = new Set(declaredRules(c).map((r) => r.id))
      const compiledIds = compiled.rules.map((r) => r.source.id)
      expect(compiledIds.filter((id) => !declaredIds.has(id))).toEqual([])
      expect(new Set(compiledIds).size).toBe(compiledIds.length)

      if (c.expectedAst) {
        for (const [ruleId, expected] of Object.entries(c.expectedAst)) {
          const rule = compiled.rules.find((r) => r.source.id === ruleId)
          expect(rule, `expectedAst names unknown rule '${ruleId}'`).toBeDefined()
          expect(write(rule!.ast as Json)).toBe(write(expected))
        }
      }

      // The outcome key set is asserted WHOLE before the values (ticket 193 review): declared keys
      // were a lower bound, so a regression emitting an unintended extra outcome while satisfying
      // every declared expectation kept the corpus green.
      const expectedOutcomes = c.expectedOutcomes ?? {}
      expect([...result.byRule.keys()].sort()).toEqual(Object.keys(expectedOutcomes).sort())
      for (const [ruleKey, expected] of Object.entries(expectedOutcomes)) {
        expect(serializeOutcome(result.byRule.get(ruleKey)!)).toBe(write(expected))
      }
    })
  }

  it('emits the cross-tier artifact', () => {
    const artifact: Record<string, Record<string, string>> = {}
    for (const c of allCases()) {
      if (c.expectedCompileError) {
        artifact[c.name] = { '(compile)': compileRefusalCode(c) }
        continue
      }
      if (c.guardValue) {
        artifact[c.name] = { [c.guardValue]: guardValueOutcome(c) }
        continue
      }
      const { result } = runCase(c)
      // Ticket 193 review: iterate the PRODUCED keys, not the declared ones. Emitting only
      // `expectedOutcomes` made the cross-tier artifact diff (runners/run-shared.mjs) a lower bound
      // as well — an extra outcome on BOTH tiers was invisible to it twice over.
      const perCase: Record<string, string> = {}
      for (const ruleKey of [...result.byRule.keys()].sort()) {
        perCase[ruleKey] = serializeOutcome(result.byRule.get(ruleKey)!)
      }
      artifact[c.name] = perCase
    }
    try {
      mkdirSync(artifactDir, { recursive: true })
      writeFileSync(join(artifactDir, 'ts-outcomes.json'), JSON.stringify(artifact, null, 2))
    } catch {
      // best-effort
    }
  })
})

