import { describe, expect, it } from 'vitest'
import { CompileError } from '../grammar.js'
import type { DecisionTableSkin } from './decision-table.js'
import { compileDecisionTable } from './decision-table.js'
import { SkinCodes } from './codes.js'

function skin(overrides: Partial<DecisionTableSkin> = {}): DecisionTableSkin {
  return {
    ruleId: 'discount',
    scope: 'Field',
    scopeTarget: 'total',
    action: 'Compute',
    hitPolicy: 'first-match',
    inputs: ['subtotal'],
    rows: [{ when: [{ kind: 'compare', op: '>=', value: 100 }], output: 10 }],
    noMatch: { kind: 'default', value: 0 },
    ...overrides,
  }
}

describe('compileDecisionTable', () => {
  it('lowers compare and bounded range cells to one multi-branch expression', () => {
    const result = compileDecisionTable(skin({
      inputs: ['subtotal', 'quantity'],
      rows: [
        {
          when: [
            { kind: 'compare', op: '>=', value: 100 },
            { kind: 'range', loInclusive: 2, hiExclusive: 5 },
          ],
          output: 'discount',
        },
      ],
      noMatch: { kind: 'default', value: 'none' },
    }))

    expect(result).toEqual({
      id: 'discount',
      tier: 'JsonLogic',
      scope: 'Field',
      scopeTarget: 'total',
      action: 'Compute',
      expression: {
        if: [
          {
            and: [
              { '>=': [{ var: 'subtotal' }, 100] },
              {
                and: [
                  { '>=': [{ var: 'quantity' }, 2] },
                  { '<': [{ var: 'quantity' }, 5] },
                ],
              },
            ],
          },
          'discount',
          'none',
        ],
      },
    })
  })

  it('orders priority rows descending while retaining declaration order for equal priorities', () => {
    const result = compileDecisionTable(skin({
      hitPolicy: 'priority',
      rows: [
        { when: [{ kind: 'any' }], output: 'first', priority: 2 },
        { when: [{ kind: 'any' }], output: 'highest', priority: 4 },
        { when: [{ kind: 'any' }], output: 'second', priority: 2 },
      ],
    }))

    expect(result.expression).toEqual({ if: [true, 'highest', true, 'first', true, 'second', 0] })
  })

  it('uses the final catch-all row as the explicit terminal else', () => {
    const result = compileDecisionTable(skin({
      rows: [
        { when: [{ kind: 'compare', op: '==', value: 'member' }], output: 'member-rate' },
        { when: [{ kind: 'any' }], output: 'standard-rate' },
      ],
      noMatch: { kind: 'catch-all' },
    }))

    expect(result.expression).toEqual({
      if: [{ '==': [{ var: 'subtotal' }, 'member'] }, 'member-rate', 'standard-rate'],
    })
  })

  it.each([
    [skin({ inputs: [] }), SkinCodes.decisionTableNoInputs],
    [skin({ rows: [] }), SkinCodes.decisionTableEmpty],
    [skin({ rows: [{ when: [], output: 1 }] }), SkinCodes.decisionTableBadRow],
    [skin({ rows: [{ when: [{ kind: 'compare', op: 'contains', value: 1 }], output: 1 }] }), SkinCodes.decisionTableBadCell],
    [skin({ hitPolicy: 'last-match' as DecisionTableSkin['hitPolicy'] }), SkinCodes.decisionTableInvalidHitPolicy],
    [skin({ noMatch: { kind: 'catch-all' } }), SkinCodes.noMatchUnresolved],
  ])('rejects invalid table input with %s', (input, code) => {
    try {
      compileDecisionTable(input)
      throw new Error('expected compilation to fail')
    } catch (error) {
      expect(error).toBeInstanceOf(CompileError)
      expect(error).toMatchObject({ code, ruleId: 'discount' })
    }
  })
})

src/__tests__/operator-catalog.test.ts.source:
/**
 * D1 ratification fix 3 (2026-07-01): the operator-catalog erosion guard — TS tier.
 *
 * A STANDING arch-test pinning the CLOSED `harborline-jsonlogic/v1` operator set + the regex-exclusion
 * invariant, so a new operator (or a regex/pattern construct) cannot slip into the evaluator at a
 * version bump without tripping this test — the "one convenience operator erodes A into B, one PR at
 * a time" (Form.io) trajectory the council named. It source-scans `jsonlogic.ts` so it is
 * author-independent. The .NET tier pins the IDENTICAL set in OperatorCatalogArchTests.cs; the two
 * frozen sets below must match, which (with each tier verifying its own source) guarantees both tiers
 * implement the same closed set.
 */
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { builtInRegister } from '../jsonlogic.js'

// The frozen, closed harborline-jsonlogic/v1 operator set (design §1.4 / README). DELIBERATELY EXCLUDED:
// any regex/pattern operator (Decision DG); map/filter/reduce/merge (deferred — folds use agg).
const FROZEN_V1_OPERATORS: ReadonlySet<string> = new Set([
  'var', 'missing', 'missing_some',
  '==', '!=', '===', '!==', '!', '!!', 'and', 'or', 'if',
  '>', '>=', '<', '<=',
  '+', '-', '*', '/', '%', 'min', 'max',
  'in', 'cat',
  'agg', 'money.add', 'money.sub', 'money.mul',
  'date.add', 'date.diff', 'date.today', 'coding.is',
])

const here = dirname(fileURLToPath(import.meta.url))
const evaluatorSrc = readFileSync(join(here, '..', 'jsonlogic.ts'), 'utf8')

describe('operator-catalog erosion guard (D1 fix 3 — TS tier)', () => {
  it('the evaluator implements EXACTLY the frozen v1 operator set', () => {
    // Since T-590 the R1 register is the evaluator's only dispatch table (rules-eng-27).
    const implemented = new Set<string>(Object.keys(builtInRegister))
    expect(implemented.size, 'the register is empty').toBeGreaterThan(0)

    const added = [...implemented].filter((op) => !FROZEN_V1_OPERATORS.has(op)).sort()
    const removed = [...FROZEN_V1_OPERATORS].filter((op) => !implemented.has(op)).sort()

    expect(added, `NEW operator(s) added without deliberate review: [${added.join(', ')}]. The harborline-jsonlogic/v1 set is CLOSED (D1) — if intended, amend FROZEN_V1_OPERATORS + the .NET arch-test + the README + design §1.4.`).toEqual([])
    expect(removed, `operator(s) removed from the evaluator: [${removed.join(', ')}]. Removing an operator breaks the closed v1 set — amend FROZEN_V1_OPERATORS deliberately.`).toEqual([])
  })

  it('the evaluator uses NO regex construct (ReDoS structurally absent — Decision DG)', () => {
    // Scoped to jsonlogic.ts (the operator dispatcher). NB: money-decimal.ts legitimately uses a `/0+$/`
    // trailing-zero trim on its OWN canonical output — that is internal formatting, not a user-pattern
    // operator, so it is deliberately out of scope here.
    for (const banned of ['RegExp', '.test(', '.exec(', '.match(', '.matchAll(', '.search(']) {
      expect(
        evaluatorSrc.includes(banned),
        `the Tier-2 evaluator must not use '${banned}': regex/pattern is excluded from v1 (Decision DG) so the ReDoS class is structurally absent. Pattern validation stays in Tier-1 JSON-Schema.`,
      ).toBe(false)
    }
  })

  it('no frozen operator names a regex/pattern construct', () => {
    for (const op of FROZEN_V1_OPERATORS) {
      for (const banned of ['regex', 'pattern', 'match', 'search']) {
        expect(op.toLowerCase().includes(banned), `operator '${op}' names a regex/pattern construct — excluded from v1 (Decision DG).`).toBe(false)
      }
    }
  })
})

src/__tests__/wf-grammar.test.ts.source:
/**
 * WF-KEY grammar extension (ADR 0140) — the net-new `wf.` / `timer.` process-context
 * addressing prefixes lower CANONICALLY (no `field.` rewrite) and are NOT extracted as
 * record-field dependencies. This is the only net-new contract surface WF-KEY adds to
 * the SPINE-1 §1.2 grammar; it keeps ONE addressing grammar across forms + workflows.
 *
 * Additive-safety: a form rule that does NOT use a wf./timer. prefix lowers byte-for-byte
 * as before — proven by the unchanged `field.` / bare-name / `self` / `section.` cases.
 */
import { describe, it, expect } from 'vitest'

import { lower, extractRefs, type LowerContext } from '../grammar.js'

const schemaCtx: LowerContext = { scope: 'Schema', scopeTarget: '', sectionId: null }

function varPath(ast: unknown): string {
  const v = (ast as { var?: unknown }).var
  return Array.isArray(v) ? String(v[0]) : String(v)
}

describe('WF-KEY wf./timer. process-context grammar', () => {
  it('lowers wf.state / wf.actor / wf.iteration canonically (no field. rewrite)', () => {
    for (const path of ['wf.state', 'wf.actor', 'wf.iteration']) {
      const ast = lower(JSON.stringify({ var: path }), schemaCtx, 'g')
      expect(varPath(ast)).toBe(path)
    }
  })

  it('lowers timer.<id> canonically', () => {
    const ast = lower(JSON.stringify({ var: 'timer.sla-clock' }), schemaCtx, 'g')
    expect(varPath(ast)).toBe('timer.sla-clock')
  })

  it('still rewrites a bare/field. name to field. (additive — no regression)', () => {
    expect(varPath(lower(JSON.stringify({ var: 'amount' }), schemaCtx, 'g'))).toBe('field.amount')
    expect(varPath(lower(JSON.stringify({ var: 'field.amount' }), schemaCtx, 'g'))).toBe('field.amount')
  })

  it('a mixed workflow guard reads form data AND process state through one lowering', () => {
    // `field.amount > 5000 and wf.iteration < 3` — the design's worked example.
    const expr = JSON.stringify({
      and: [
        { '>': [{ var: 'field.amount' }, 5000] },
        { '<': [{ var: 'wf.iteration' }, 3] },
      ],
    })
    const ast = lower(expr, schemaCtx, 'guard-1') as Record<string, unknown>
    const and = ast.and as unknown[]
    const gt = (and[0] as Record<string, unknown>)['>'] as unknown[]
    const lt = (and[1] as Record<string, unknown>)['<'] as unknown[]
    expect(varPath(gt[0])).toBe('field.amount')
    expect(varPath(lt[0])).toBe('wf.iteration')
  })

  it('does NOT extract wf./timer. as field/row deps (they are external context, not cells)', () => {
    const expr = JSON.stringify({
      and: [
        { '>': [{ var: 'field.amount' }, 5000] },
        { '<': [{ var: 'wf.iteration' }, 3] },
        { '>': [{ var: 'timer.sla-clock' }, 0] },
      ],
    })
    const ast = lower(expr, schemaCtx, 'guard-1')
    const refs = extractRefs(ast)
    // Only the real form field participates in the dependency graph.
    expect(refs).toEqual([{ kind: 'field', name: 'amount' }])
  })

  // T-741 (codex review finding): the .NET tier preserves `candidate.` as a declared context
  // prefix (like `wf.`/`timer.`) so Rules' admission check can refuse an undeclared reference
  // instead of it being silently rewritten into a field read. This tier must lower it
  // identically, or a guard the .NET publish check refuses would still resolve (wrongly) as a
  // field read here — a fail-closed gap across tiers.
  it('lowers candidate.<name> canonically, like wf./timer. (T-741 cross-tier parity)', () => {
    const ast = lower(JSON.stringify({ var: 'candidate.status' }), schemaCtx, 'g')
    expect(varPath(ast)).toBe('candidate.status')
  })

  it('does NOT extract candidate. as a field/row dep', () => {
    const ast = lower(JSON.stringify({ var: 'candidate.status' }), schemaCtx, 'g')
    expect(extractRefs(ast)).toEqual([])
  })
})

